INSERT INTO rol_permiso (rol_id, permiso) SELECT id, permiso FROM rol, (VALUES ('MED_CONSULTAR'), ('PREST_CONSULTAR'), ('AGEN_CONFIGURAR'), ('AGEN_CONSULTAR'), ('PACIENTE_CONSULTAR'), ('TURN_REPROGRAMAR'), ('TURN_CANCELAR'), ('TURN_ANUNCIAR'), ('TURN_INICIAR'), ('TURN_FINALIZAR'), ('TURN_CONSULTAR') ) AS permisos(permiso) WHERE rol.nombre = 'Medico';
